INSERTS=[('q-002',dict(meta='야마 · 0/0 · 야마 2025 객71 · 학습지 746쪽 원문대조 (앱에서 누락되어 추가)',
  stem='뇌졸중 후 재활치료에 대한 설명으로 가장 중요한 개념은 다음 중 무엇인가?',
  choices=['마비된 팔다리에 필요한 보조기를 장착하여 기능을 도와주는 것이다.','장애가 생긴 부위를 남겨두고 더 이상의 합병증을 생기지 않게 한다.','장애가 생기지 않도록 교육하고 적절한 약물을 투약하는 것이다.','장애가 있음을 인정하고 이에 맞는 생활패턴을 교육하는 것이다.','손상된 뇌를 치료 타겟으로 하여 다시 회복되도록 뇌를 치료하는 것이다.'],ans=[5],
  basis='뇌질환 환자의 재활치료란 손상된 뇌를 치료 타깃으로 하여 뇌의 가소성을 이용해 손상된 뇌가 최적으로 재조직화(reorganization)되어 살아날 수 있도록 증명된 최상의 치료를 하는 것(2025 성인뇌질환재활 강의록 7p). "마비는 어쩔 수 없다"가 아니라 손상된 뇌 자체를 치료하는 것이 중요하다고 강조.',
  exps=['보상적 접근일 뿐 가장 중요한 개념은 아니다.','합병증 예방만으로는 부족하다.','예방·약물 중심의 설명이다.','장애 수용·적응만 강조하는 것은 교수님 강조점과 반대이다.','정답. 손상된 뇌를 치료 타깃으로 한 재조직화.']))]
